globalThis.ANDE_CHUNKS["4474ab6961f9601234be2acc9465333712599272363d12ec2d09c3c8fceea82f"] = [{"id":"netease_leihuo:13009","sourceKey":"netease_leihuo","company":"网易雷火","title":"游戏测试开发实习生（无限大）","city":"杭州市","category":"游戏测试-游戏测试开发-游戏测试开发","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://hr.163.com/job-detail.html?id=13009&lang=zh","duty":"您可以：\n1、作为业内优秀测试团队的一员，分析产品最新功能特性的设计方案，找出设计中潜在的问题，从源头保障游戏质量；\n2、最先接触和体验新游戏新玩法，剖析产品方方面面，制定每个阶段的测试计划；\n3、全面详尽地对产品进行测试，找出各类bug及其根源，并协助研发工程师进行修复，直至问题得到彻底解决；\n4、钻研和开发各种辅助测试工具，编写自动化测试脚本，进行性能分析和安全评估，不断提高测试效率，全方面改进产品质量和用户体验；\n5、对产品每一个版本的发布风险及发布质量进行全面评估，推动产品质量及过程质量的持续改进，成为质量保证专家。","requirements":"我们希望您具备以下条件：\n1、本科及以上学历，理工科专业（计算机相关专业尤佳）；\n2、良好的沟通能力，能清晰、准确的在团队中传达自己的想法；\n3、强烈的质量意识以及解决问题的意愿，关注产品、技术、过程的持续改进；\n4、扎实的技术基础，精通一种以上编程语言及其思想，有python或lua开发经验者尤佳；\n5、热爱游戏，愿意在游戏行业一展才华，有丰富游戏经验者尤佳。\n该岗位欢迎2027届及以后毕业同学，实习表现优秀将有转正机会\n【请务必注意】投递该岗位，简历需附带游戏经历（含游戏名称、时长/段位等信息）\n【请务必注意】该岗位需在offer后2周内到岗，实习时长不得少于5个月。请在简历里补充最快到岗时间及实习时长。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:15994","sourceKey":"netease_leihuo","company":"网易雷火","title":"游戏文案策划实习生","city":"杭州市","category":"游戏策划-文案策划-文案策划","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://hr.163.com/job-detail.html?id=15994&lang=zh","duty":"1、根据提供的故事剧本，设计并制作出表现力优秀且可玩性强的任务流程。\n2、对动画或者电影镜头有一定了解，并且能根据剧情需要制作出相应的对话镜头和简易动画。\n3、根据剧情表现提出合理的美术资源需求和程序功能需求，对任务流程进行全面管理。\n4、根据玩家体验与反馈，对剧情任务线进行优化跟进，提升剧情表现力。\n5、世界观、文案包装等相关工作。","requirements":"1、专业不限，27届及以后毕业的同学优先。\n2、具有不错的写作功底，口头沟通表达能力好。\n3、逻辑性较强，有一定主动性和责任心，自我管理较好。\n4、对office系列的工作软件有操作基础。\n5、热爱游戏，对影视、动漫、摄影、命理有所研究，在历史、中文、哲学专业上有所建树。\n6、每周至少实习5天，至少实习4-6个月，有相关领域实习经历者优先。\n【投递请附带详细游戏经历与文案作品！】","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:19310","sourceKey":"netease_leihuo","company":"网易雷火","title":"游戏关卡策划实习生（无限大）","city":"杭州市","category":"游戏策划-关卡策划-关卡策划","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://hr.163.com/job-detail.html?id=19310&lang=zh","duty":"1. 根据项目需求完成游戏内的PVE关卡或活动的设计和制作。\n2. 和其他策划配合完成各关卡中的副本流程、怪物和首领等配置。\n3. 和策划、程序、美术和QA等岗位积极沟通协作，在保证质量的前提下按时完成关卡。\n4. 对自己所参与或负责的关卡进行总结和分析，结合用户体验不断优化完善关卡。","requirements":"1.欢迎投递本岗位者提供作品集。\n2. 具备良好的逻辑思维能力，能很好的理解底层实现。有代码经验更佳。\n3. 具备良好的审美能力，可以和美术很好的协作。\n4. 具备良好的沟通表达能力，乐于和其他同事沟通讨论，协作力强。\n5. 具备一定创新能力，善于总结思考提高。执行力强，有一定的抗压能力。\n6. 熟悉主机游戏和二次元游戏的关卡，有深度体验更佳。\n【投递请附带详细游戏经历】","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3403","sourceKey":"netease_leihuo","company":"网易雷火","title":"非欧几何游戏场景的描述和实现","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3403&projectId=68","duty":"研究非欧几何游戏场景的描述和实现，用于提高游戏场景的设计感，为策划和美术提供更多可创作的空间。","requirements":"1.计算机或相关专业，本科及以上学历；\n2.热爱游戏和游戏开发；\n3.精通C/C++编程语言及其思想；\n4.扎实的计算机基础知识，深入理解数据结构，算法，操作系统等知识；\n5.良好的逻辑综合分析能力，以及强烈的解决问题的意愿；\n6.强烈的求知欲，和与之相适应的学习能力；\n7.良好的沟通能力，能清晰、准确的在团队成员中传达自己的想法；\n8.有计算机图形学基础，熟悉一种或多种图形API，如DirectX 11/12，OpenGL，Vulkan或Metal。\n加分项：\n1.有渲染和图形学相关技术实践经验；\n2.熟悉或精通深度学习相关技术；\n3.熟悉一种或多种商业游戏引擎，如Unity3D，UnrealEngine等。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3407","sourceKey":"netease_leihuo","company":"网易雷火","title":"预测型Foot IK研究和实现","city":"杭州","category":"游戏引擎","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3407&projectId=68","duty":"背景：\n在游戏开发中，需要利用Foot IK技术修正角色的动作来适配崎岖的地形，使得脚和腿不会与地面发生穿插，主流的方案对于静止的动作处理的很好，但是对于移动中动作的处理还不尽如人意，在流畅度和防止穿插的表现上还不够好。因此需要研究预测型Foot IK，提前获取角色未来的落脚点，对腿和脚的IK目标位置进行动态调整，来得到更好的动作表现。\n目标： 本课题的目标在于研究预测型Foot IK的实现，并能够应用在带Root Motion的动画上，使得移动中角色的脚和腿能够更流畅、准确的处理与地面的关系。","requirements":"1、计算机、软件、数字媒体、计算机图形学、数学、物理等相关专业；\n2、热爱游戏和游戏开发；\n3、熟练掌握C/C++语言，扎实的计算机基础知识，深入理解数据结构，算法，操作系统等知识，良好的编程能力；\n4、具备基本的计算机图形学基础，熟悉骨骼动画的基本原理；\n5、良好的逻辑综合分析能力、解决问题的能力及及动手能力，强烈的求知欲，和与之相适应的学习能力；\n6、良好的沟通能力，能清晰准确的在团队成员中传达自己的想法。\n具备以下条件为加分项：\n1、有计算机动画、游戏动作技术相关的开发或实习经验，了解或实现过反向动力学(IK)；\n2、熟悉一种或多种商业游戏引擎，如Unity3D，UnrealEngine等。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3410","sourceKey":"netease_leihuo","company":"网易雷火","title":"移动端着色语言性能分析与验证","city":"杭州","category":"游戏引擎","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3410&projectId=68","duty":"从阅读《Low-Level Thinking In High-Level Shading Languages》出发，对移动端高级着色语言的性能优化技巧进行总结。作者称文中大部分优化建议是适用于任何GPU的，但实际上只在Radeon HD4870进行了测试，因此这些结论在移动平台是否依然适用是一个值得进一步确认的问题。本课题需要针对不同类型的移动设备进行着色语言写法的性能分析与验证，最后的结论对移动平台开发具有指导性意义。","requirements":"良好的计算机、图形学基础，熟悉常用的着色语言，熟悉常用的移动端GPU性能分析工具（如XCode、RenderDoc、Snapdragon Profiler、Arm Mobile Studio等）","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3411","sourceKey":"netease_leihuo","company":"网易雷火","title":"shader跨平台编译研究","city":"杭州","category":"游戏引擎","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3411&projectId=68","duty":"许多新的渲染特性依靠新的shader语法, 但引擎不一定支持, 文本替换方式添加容易出现限制或bug","requirements":"了解现有跨平台编译工程例如spir-v cross工程, 掌握项目结构,开发与测试方式, 能在这工程上去客制化新语法支持, 并看怎样接入或更动现有引擎框架","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3412","sourceKey":"netease_leihuo","company":"网易雷火","title":"材料点法的实时雪崩模拟","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3412&projectId=68","duty":"介绍：\nMPM是一种计算力学方法，最初用于模拟固体材料的动态行为。它结合了拉格朗日法和欧拉法的优点，能够准确地处理大变形、断裂和流体-固体相互作用等复杂问题。MPM在近年来得到了广泛的应用，并逐渐成为固体力学仿真领域的重要工具。雪崩的动态裂纹扩展的连续数值模拟也是一个巨大的挑战。本课题尝试在实时渲染中通过各种优化手段，尽可能做到渲染质量和性能的平衡，在实时渲染中实现雪崩效果。\n应用场景：\nPS5，PC端 UE5引擎","requirements":"1. 熟练使用C/C++，熟悉常用的脚本语言（Python最佳），熟悉shader语言如hlsl, glsl等；\n2. 熟悉3D图形学知识，具备良好的算法和数学基础；\n3. 对游戏引擎中渲染、动画、特效等模块有深入了解，能独立扩展引擎的底层模块；\n4. 具备较强的自驱力，能主动探索解决方案并实现；\n5. 熟悉商业引擎或开源引擎如Unreal，Unity, Godot等，有引擎开发经验者优先；\n6. 有物理模拟，仿真相关经验优先；\n7. 对于前沿的技术有一定的敏锐度和较强的兴趣，不断学习，并尝试创新。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3413","sourceKey":"netease_leihuo","company":"网易雷火","title":"基于光追系统的超多数量、多类型光源光照渲染方案","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3413&projectId=68","duty":"目前硬件光追逐年进步，趋于完善，在布局未来技术方案上需要先人一步，做好技术积累。该方案可用于几乎所有类型的游戏，且解放美术限制，可以任由美术发挥。光线追踪带来的准确性是光栅化技术无法相比的，能生产出十分接近物理世界的光照效果，极大提高玩家游戏体验。该课题主要目标是完成在巨量（成千上万），多类型（直接光，点光，聚光，面光等）光源的环境中展示出接近真实光照的效果（优先直接光，有机会再做间接光），且能保证实时渲染效率（60fps以上）。","requirements":"1.计算机或相关专业，本科及以上学历；\n2.有良好的图形学基础，理解常见的渲染知识；\n3.熟练使用 C++ ，熟悉基于dx12或vulkan 的 RT 渲染管线架构 ；\n4.算法能力优秀，熟悉各种常见的光照模型，熟悉至少一款商业引擎（unity，ue）渲染管线架构；\n5.沟通能力优秀、学习能力强，勇于尝试新技术；\n6.热爱游戏和游戏开发。\n加分项：了解目前已经在游戏中使用过的各种RT技术","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3414","sourceKey":"netease_leihuo","company":"网易雷火","title":"基于GPU Work Graph的BVH Culling算法","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3414&projectId=68","duty":"方向:\nGPU 性能\n简述:\nGPU Work Graph是一套新的GPU 编程范式, 微软 NV AMD现在都有公开的Demo展示;\n该技术可以提升HWRT, GPU Driven性能, 对通用GPU编程有结构性的改进;\n各种高级BVH算法现在被应用在GPU RT单元, Nanite等前沿技术中, 现有的BVH culling存在GPU均衡的问题, Nanite对自己的BVH做了一套多写多读的算法, 该课题希望实现一套对GPU友好的BVH算法, 并利用Work Graph对BVH进行剔除, 最好能针对Nanite做一版Work Graph的优化;\n参考资料: https://microsoft.github.io/DirectX-Specs/d3d/WorkGraphs.html","requirements":"前置要求:\n需要懂gpu driven思路, 基础的GPU硬件知识, 最好对UE5 Nanite渲染管线有一定了解;","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3415","sourceKey":"netease_leihuo","company":"网易雷火","title":"布料解算物理上采样","city":"杭州","category":"游戏引擎","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3415&projectId=68","duty":"布料解算可以大大增强游戏的物理真实感，但其模拟和碰撞的高开销限制了柔布的精细程度和泛用性，尤其在移动设备上。一种可能的方法是先只对低模进行物理模拟，形成布料大致的整体造型后，再增加褶皱等细节，实现更加逼真的高模效果。该课题的主要目标是在低模物理模拟（如动画、动骨、低面片数柔布）基础上，实现符合物理预期、视觉效果美观的高模布料解算，要求效果稳定鲁棒、开销低于常规的柔布解算、基本不穿模、在不同帧率效果接近，并可以在移动端落地应用。","requirements":"1.计算机或相关专业，本科及以上学历\n2.熟练掌握C++，有一定图形学基础，算法能力好，编程能力扎实\n3.在实时物理模拟上有一定实践经验\n4.沟通能力、学习能力强\n5.热爱游戏和游戏开发。\n加分项：对Unity、UE引擎其中一款引擎有使用经验。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3416","sourceKey":"netease_leihuo","company":"网易雷火","title":"PCG城市生成","city":"杭州","category":"程序化生成","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3416&projectId=68","duty":"通过PCG技术生成超大规模城市，研究自动化生成技术，落地到实际的项目中","requirements":"有houdini的相关经验\n有至少一门编程语言的经验\n有建筑学背景优化","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3417","sourceKey":"netease_leihuo","company":"网易雷火","title":"卡通渲染技术","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3417&projectId=68","duty":"参与卡通风格游戏的材质实现工作，调研和实现各类卡通风格的材质效果和渲染技术","requirements":"有shader的编写经验\n有良好的图形学基础","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3418","sourceKey":"netease_leihuo","company":"网易雷火","title":"高品质动态GI渲染","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3418&projectId=68","duty":"调研高品质Real-Time GI的实现算法，用于支撑AAA级游戏的核心光照。","requirements":"1.计算机或相关专业，本科及以上学历；\n2.图形学有良好的基础，理解常见的渲染知识；\n3.沟通能力、学习能力强；\n4.在渲染上有一定实践经验；\n5.算法能力好，编程能力扎实；\n6.热爱游戏和游戏开发。\n加分项：\n对Unity、UE引擎其中一款引擎有使用经验。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3419","sourceKey":"netease_leihuo","company":"网易雷火","title":"超大规模城市光影技术","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3419&projectId=68","duty":"实时光影对实现逼真的城市场景至关重要，更多的细节能够增加游戏环境的真实感，让玩家更好地融入游戏世界，提升沉浸感与视觉享受。移动平台也逐渐需要支持大规模城市场景夜景支持，实现与PC平台相近的视觉效果，移动端渲染特性、性能和功耗的限制对优化带来了非常大的挑战。该课题的主要目标是实现全平台的24小时光照阴影（1500+m阴影距离）、上千盏同屏实时灯光和阴影的支持，并满足60帧的渲染效率与移动端功耗的需求。","requirements":"1.计算机或相关专业，本科及以上学历；\n2.图形学有良好的基础，理解常见的渲染知识；\n3.沟通能力、学习能力强；\n4.在渲染上有一定实践经验；\n5.算法能力好，编程能力扎实；\n6.热爱游戏和游戏开发。\n加分项： 对Unity、UE引擎其中一款引擎有使用经验。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3420","sourceKey":"netease_leihuo","company":"网易雷火","title":"强叙事单机剧情角色表现","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3420&projectId=68","duty":"随着互动叙事与沉浸式体验需求的攀升，游戏不再仅仅是玩法的载体，更是情感表达的媒介，电影化叙事已成为次世代单机大作的标配。然而，传统统一的全局环境光往往难以兼顾角色面部微表情的细腻呈现，且不同剧本基调对画面风格有着差异化的严苛要求。本课题旨在构建一套影游融合的高品质角色镜头渲染表现方案，聚焦于角色专属的动态布光、材质光影表现等方面，确立高规格的单机画面质感。研究将致力于打造情感穿透力极强的角色实时过场演出。","requirements":"1. 计算机、数字媒体技术或相关专业，本科及以上学历\n2. 熟悉 Unity 或 UE引擎，具备扎实的图形学基础，理解PBR流程\n3. 熟练掌握 C++/C# 语言，具备优秀的 Shader (HLSL/GLSL) 编写能力，熟悉渲染管线\n4. 理解电影化布光理论，熟悉实时动态布光技术及阴影算法，对摄影机后处理特效有研究\n5. 具备良好的审美、研究能力 6. 热爱单机游戏或互动电影类游戏","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3421","sourceKey":"netease_leihuo","company":"网易雷火","title":"超大规模场景实时光线追踪渲染","city":"杭州","category":"渲染表现","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3421&projectId=68","duty":"随着GPU硬件日益发展，PC端硬件光追已经逐渐普及，移动端硬件光追也已经悄然进入人们的视野，实时硬件光追技术无疑是下一代PC/移动端游戏发力的重点。光追技术对画面提升的同时，也对性能提出了较大的挑战。面对不断扩大的游戏场景规模、视距，实时大范围高精度光追是目前面临的一大难题。该课题主要目标是完成大规模场景下全实时（60fps以上）光线追踪渲染，包括但不限于反射、GI、AO、阴影等。","requirements":"1. 计算机或相关专业，本科及以上学历；\n2. 熟悉Unity/Unreal引擎，图形学有良好的基础，理解常见的渲染知识；\n3. 掌握C++，C#等语言，shader开发，熟悉DX12，Vulkan，Metal等图形接口\n4. 研究能力强，熟悉业界前沿渲染技术，善于学习跟分享\n5. 热爱游戏和游戏开发。\n加分项： 有光追相关开发经验","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3422","sourceKey":"netease_leihuo","company":"网易雷火","title":"PCG城市群生成算法研究","city":"杭州","category":"程序化生成","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3422&projectId=68","duty":"PCG技术在大体量游戏开发中落地前景较好，存在大量可探索空间。\n此课题有如下细分课题可供选择：\n1.现代曲面结构建筑生成\n2.中/欧式古建筑生成\n3.空间布局算法\n同学可选至少一项进行研究，有落地潜力的同学可提前签约参与项目的长期研发。","requirements":"1. 计算机图形学、建筑学相关专业；\n2. 编程基础扎实，善于编写算法解决排列、分布、几何构建问题；\n3. 掌握Unity/Unreal的使用；\n加分项：\n1.熟练使用Houdini\n2. 有游戏引擎工具开发经验\n3.有特色的程序化生成Demo展示\n4.有交互设计能力","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3423","sourceKey":"netease_leihuo","company":"网易雷火","title":"结合AI的前期程序化纹理生成","city":"杭州","category":"程序化生成","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3423&projectId=68","duty":"该课题主要解决的问题：项目关卡前期的大量代理贴图的效果预览，比起传统的制作流程会更快，也期待更好的视觉效果。使用GhatGPT或者其他大模型来更好的完善描述文字，结合midjoyrney和stable diffusion来生成所需要的材质，后期的处理需要加入Adobe的程序化材质生成工具完成整套流程。","requirements":"1、计算机或者游戏类相关专业，本科及以上学历\n2、有一些基本的AI工具使用经验，能够解决一些工作效率上的问题\n3、有材质贴图制作经验，熟练 Adobe Substance Designer\n4、良好的艺术审美能力\n5、良好的沟通能力，能积极主动的发现问题，并尝试提出解决方案","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3427","sourceKey":"netease_leihuo","company":"网易雷火","title":"基于数据闭环的Agent调优","city":"杭州","category":"AI-Agent","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3427&projectId=68","duty":"通过Agent接入各项业务需求已经成为当下的必选路径之一，然而“开发易，调优难”制约了Agent落地的实际效果。如何构建全面的评测体系、搭建有效的数据闭环，尤其探索无需额外训练的training-free优化方案，正成为突破Agent调优瓶颈、实现业务价值最大化的核心关键路径。在本课题中，你将会： 1. 参与人设对话、HR助手等业务场景的Agent工程化及效果调优。 2. 参与构建可支持动态更新的评测体系，或从用户反馈训练Reward Model。 3. 参与构建基于符号体系的Agent自动化调优闭环框架。","requirements":"1. 在大模型或Agent领域有相关的科研和落地经历。\n2. 熟悉大模型SFT、RLHF等训练技术。\n3. 自驱力强，善于思考，给定课题能够进行深入研究和顶会文章发表。\n加分项：\n1. 深度参与的Agent业务调优经历。\n2. 顶会一作大模型相关论文。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3428","sourceKey":"netease_leihuo","company":"网易雷火","title":"AI原生游戏Agent研发","city":"杭州","category":"AI-Agent","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3428&projectId=68","duty":"AI 游戏正从 “AI-enhanced”迈向“AI-native”：AI 不再局限于制作管线提效，而将深度融入核心玩法、内容生产与交互机制，推动下一代游戏范式与差异化体验成形。在本课题中，你将会： 1. 参与AI原生游戏的全流程研发，负责游戏垂域 AI Agent的架构设计、模型训练与能力评估。 2. 跟踪 LLM/Agent 领域前沿进展，推动其在玩法设计、关卡生成与数值调控等场景的创新落地。 3. 运用 SFT、RL 等后训练技术，提升（多模态）LLM 在规划推理、RAG、工具调用与内容生成等关键能力，形成可复用、可规模化的游戏 AI Agent 解决方案。","requirements":"1. 掌握 LLM 核心原理与工程化实践，具备在 RAG、Prompt 工程、SFT/RL 等方向的落地能力，熟悉 AI Agent 的架构设计与实现。\n2. 熟悉 LangGraph、Dify 等主流 Agent 开发框架，有完整 AI Agent 搭建与集成经验者优先。\n3. 深度游戏玩家、有游戏研发经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3429","sourceKey":"netease_leihuo","company":"网易雷火","title":"去中心化的Agent画像体系建设","city":"杭州","category":"AI-Agent","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3429&projectId=68","duty":"研究方向\n聚焦Web3.0生态下区块链用户行为数据的价值挖掘，核心攻克“隐私保护合规性”与“用户画像准确性”双重核心目标，构建适配区块链场景特性的隐私保护型用户画像体系，助力Web3.0应用实现精准化运营与合规化发展。\n工作内容\n1. 设计隐私保护型区块链用户画像体系框架，解决传统画像技术在区块链数据碎片化、公开性场景下的适配问题。优化区块链用户特征提取、融合及建模过程。\n2. 构建实验验证体系，基于真实区块链数据集开展隐私保护性、画像准确性测试，迭代优化体系架构与技术方案。\n3. 结合有灵智能体人机协作任务场景，开展相关用户画像实验，验证技术方案的落地价值。\n4. 撰写研究报告、学术论文或发明专利，沉淀理论与实践成果。","requirements":"1. 本科及以上学历，计算机、大数据、信息安全、金融科技等相关专业，有区块链或用户画像领域研究/实践经验者优先。\n2. 具备较强的问题解决能力和工程能力。熟练使用Python、SQL等数据处理工具及相关机器学习框架。能独立完成区块链数据集的采集、清洗、预处理及实验验证工作。\n3. 具备良好的文档撰写与学术研究能力，能独立完成研究报告、论文及方案输出。\n4. 有团队协作精神，能配合完成跨模块技术研发、实验验证及案例落地工作。\n5. 有该岗位相关（区块链、隐私保护、用户画像等方向）高水平论文发表者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3430","sourceKey":"netease_leihuo","company":"网易雷火","title":"大模型向量表征和检索","city":"杭州","category":"大模型","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3430&projectId=68","duty":"随着LLM的发展，游戏中逐渐出现了AI驱动的智能NPC，给玩家带来了新鲜的交互体验和情感陪伴。为了让NPC成为有记忆、可长期交互的智能体，NPC需要处理并记住大量的交互信息，包括玩家对话、游戏事件、NPC自我决策的行为，等等。如何将这些信息转换成语义向量，被NPC合理检索使用，是一个十分重要的课题，也是影响玩家和智能NPC交互体验的重要因素。 在本课题中，你将会：\n1、深度参与AI检索系统的构建，包括多模态、多场景的信息编码与检索；\n2、与产研团队紧密结合，将检索系统落地于游戏智能NPC中，共建智能NPC的“大脑”。","requirements":"1、计算机、AI等相关专业在读，博士优先；熟悉机器学习、深度学习、自然语言处理的基础知识，掌握至少一种深度学习框架、大模型推理框架等，能够自主训练并部署模型。\n2、具备扎实的计算机基础，熟练掌握Python；热爱新技术、有创新性思维、较强自驱力、团队协作精神和沟通能力。\n3、在NLP相关比赛中获奖 、或发表NLP顶会paper加分；有向量检索相关项目经验、向量数据库使用经验加分。\n4、对游戏行业热爱，游戏重度玩家，对玩家生态与社区文化有一定理解加分。\n5、实习期4个月及以上。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3431","sourceKey":"netease_leihuo","company":"网易雷火","title":"多模态AI-Agent生产管线建设","city":"杭州","category":"AI-Agent","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3431&projectId=68","duty":"我们正在寻找一位 学习能力强、动手快、对大模型技术充满热情的同学 加入我们，你将参与内部的 LLM 基础设施的开发建设工作，推进 AI Agent 应用的实际落地，包括但不限于：\n1、参与 LLM 基础设施开发，包括不限于 Prompt 工作台、Agent、RAG、评测平台、模型服务、数据优化管线 等；\n2、使用 AI 开发工具构建 Web 前端/后端 应用，服务部署和性能优化；\n3、与 AI 产研团队紧密协作，推动应用在内部落地。","requirements":"1、计算机相关专业，基础扎实，学习动手能力强，熟悉Python编程语言，具备一定的 Web 应用开发经验\n2、做事认真靠谱，思维敏捷，沟通顺畅，愿意主动解决问题\n3、有前端经验优先（如 React / Next.js / TypeScript 等），熟悉各种 Coding CLI、Cursor 等 AI 开发工具优先\n4、有机器学习/深度学习相关知识加分\n5、实习期4个月及以上","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3432","sourceKey":"netease_leihuo","company":"网易雷火","title":"游戏AI Agent智能舆情分析","city":"杭州","category":"AI-Agent","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3432&projectId=68","duty":"随着大模型（LLM）的快速发展，游戏舆情分析领域涌现出AI驱动的智能系统，能够实时监测玩家反馈、舆情事件和热点趋势，为游戏迭代优化提供强有力的数据支撑。为了让AI-Agent成为高效的舆情处理智能体，它不仅需处理海量的多模态舆情信息，还需实现及时有效的热点推送、智能化的信息编排，以及个性化的交互式决策辅助，进一步提升效能。在本课题中，你将会： 1、参与公司游戏 AI 舆情项目研发，构建能够快速响应玩家反馈、支持游戏迭代优化的智能分析与处理能力。 2、参与 AI-Agent 在游戏舆情体系中的核心能力建设，包括函数生态、多工具协同与知识增强等方向，提升Agent 处理玩家反馈、舆情事件、热点分发等任务的自动化水平。 3、优化 Agent 多工具协同策略，提高舆情任务的自动化与决策准确性。","requirements":"1、计算机相关专业，熟练掌握 Python 及基本工程开发能力。\n2、熟悉现有AI-Agent开发工具，具备良好的问题分解能力，沟通顺畅，自驱性强。\n3、对 AI-Agent 的典型范式有一定了解，如 MCP Function、ReAct、Tool Calling 等。\n4、对游戏行业热爱，重度玩家优先，对玩家生态与社区文化有一定理解加分。\n5、实习期4个月及以上","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3433","sourceKey":"netease_leihuo","company":"网易雷火","title":"基于LLM的决策智能","city":"杭州","category":"大模型","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3433&projectId=68","duty":"在 MMORPG 游戏中，存在大量的智能 NPC，这些智能 NPC 可以和用户进行各种交互，交互形式不限于智能对话、心理活动、行为动作、日常活动，我们希望通过大型语言模型 (LLM) 的技术来驱动 NPC 的行为，让 NPC 们在不同场合下可以做出合理的行为（比如对话欢乐时会做出微笑的表情、用户说饿了可以送用户西湖醋鱼），体现出拟人化的智能程度，不同场合不限于 NPC 的人设维度、环境维度、行为空间维度等。本课题将探索如何应用 LLM 来实现决策智能，以及如何提升 LLM 的决策能力，最后将决策结果应用于游戏中的 NPC，提升用户的游戏体验。","requirements":"1、计算机基础扎实，编程能力良好，具备机器学习、自然语言处理、预训练语言模型基础知识；\n2、熟练使用主流深度学习框架（pytorch等），能够主动follow前沿研究成果并独立复现，有实践经历者优先；\n3、对 Agent 有经验或者有强烈兴趣者优先；\n4、对游戏+AI有强烈兴趣，热爱游戏者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3434","sourceKey":"netease_leihuo","company":"网易雷火","title":"游戏智能NPC的多模态交互探索","city":"杭州","category":"AI-Agent","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3434&projectId=68","duty":"多模态交互是指通过感知多种模态信息（如文字、图像、语音等），帮助人工智能更准确地理解外部世界。它涵盖了表征学习、跨模态对齐、跨模态理解、跨模态生成（AIGC）、多模态融合等子任务。在游戏智能NPC的场景中，多模态技术有着非常重要的作用。它不仅能够增强对用户情感和意图的理解，还能拓宽交互方式和应用场景，为用户提供更高效和愉悦的交互体验。通过融合多种感知模态，NPC能够更全面地理解用户的输入，并根据语音、图像等信息提供个性化的反馈和互动。这种交互方式不仅提升了游戏体验的沉浸感，还为玩家创造了更多元化的互动可能性，使游戏更具吸引力和趣味性。本课题将针对多模态技术在游戏智能NPC中的落地进行深入研究，为玩家提供更加丰富和有趣的游戏体验。","requirements":"1、计算机基础扎实，编程能力良好，具备机器学习、自然语言处理、计算机视觉、预训练语言模型、多模态的基础知识；\n2、熟练使用主流深度学习框架（pytorch等），能够主动follow前沿研究成果并独立复现，有实践经历者优先；\n3、具备NLP&CV&多模态&大模型相关比赛获奖 / 人工智能顶会paper / 开源项目开发经验者优先；\n4、对游戏+AI有强烈兴趣，热爱游戏者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3435","sourceKey":"netease_leihuo","company":"网易雷火","title":"人设对话","city":"杭州","category":"大模型","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3435&projectId=68","duty":"人设对话是游戏智能 NPC 的核心交互基石，其核心价值在于构建 “有温度、有人设一致性” 的虚拟交互场景，远超基础问答功能。它需支撑 RPG 中 NPC 依据玩家剧情选择延续情感对话、开放世界日常互动适配，实现跨场景通用性；更要赋能 UGC 创作，让模型快速适配玩家自定义人设，助力玩家从 “剧情参与者” 升级为 “NPC 人设创作者” 。 岗位职责： 本岗位针对人设对话课题进行研究，研究方向包括但不限于： 1、对话评估：探索标准的对话评测方案、开展自动化评测方案的研究； 2、数据集：探索人设设定数据、多轮交互数据、对话偏好数据的构建方式。 3、模型：探索人设对话场景下SFT、RL、COT的技术方案。 4、 智能体：探索人设对话场景下长期记忆、规划、反思等智能体的技术方案。","requirements":"1. 对深度学习、大语言模型有深入的理解和实践经历；\n2. 有对话系统/角色扮演/故事生成等文本生成相关方向的研究或实践经验；\n3. 对大模型前沿研究保持敏锐关注，熟悉大模型预训练、后训练等技术；\n4. 自驱力强，善于思考，给定课题能够进行深入研究和顶会文章发表。\n加分项：\n1. 在人工智能的顶级会议(如：ICLR、NeurIPS、ACL、EMNLP等）上发表过论文（一作）；\n2. 有大语言模型Pretrain、SFT、RLHF、RLVR等研究或实践经验。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3436","sourceKey":"netease_leihuo","company":"网易雷火","title":"自动蒙皮","city":"杭州","category":"图形图像","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3436&projectId=68","duty":"在当前的游戏开发流程中，从角色建模到最终的动画呈现，蒙皮技术扮演着承上启下的关键作用，直接影响着角色动作的自然度和视觉表现力。 传统的角色蒙皮工作流程高度依赖专业的技术美术人员手工完成。技术美术师需要根据角色的解剖结构和预期的动画需求，精确设置每个顶点对应骨骼的权重分配，确保角色在各种动作姿态下都能呈现出自然的变形效果。这一过程不仅技术门槛高，需要丰富的人体解剖学知识和多年的实践经验，而且极其耗时耗力。对于一个复杂的游戏角色，完整的蒙皮工作往往需要数天甚至数周的时间，随着游戏内容的丰富化和个性化需求的增长，现代游戏往往需要大量的角色模型。从主角到NPC，从装备变化到角色定制，每一个新的角色变体都需要重新进行蒙皮处理，严重制约了游戏开发的整体效率。 近年来，深度学习和人工智能技术在计算机图形学领域取得了显著突破，为解决自动蒙皮这一长期技术难题提供了新的思路。基于神经网络的几何处理方法在3D模","requirements":"1. 计算机视觉或图形学相关方向，硕士或博士在读；\n2. 熟悉计算机视觉或图形学领域的主流模型和算法，有3D生成，视频生成，多模态大模型，3D重建，3D人脸/头发/人体等其中一项或多项相关算法知识优先；\n3. 计算机基础扎实，熟悉TensorFlow、Pytorch等框架，能熟练运用python、C/C++实现算法；\n4. 关注领域内的最新进展，在相关领域顶级会议（CVPR/ICCV/ECCV/NIPS/SIGGRAPH等）发表过高质量论文者优先；\n5. 专注、自驱，有强烈的探索精神及深入思考的能力。 6. 有良好的团队合作和沟通能力。","description":"","jdComplete":false,"sourceStatus":null},{"id":"netease_leihuo:3437","sourceKey":"netease_leihuo","company":"网易雷火","title":"3D角色生成","city":"杭州","category":"图形图像","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.163.com/app/detail/index?id=3437&projectId=68","duty":"游戏角色的智能创建功能，特别是允许玩家个性化定制虚拟形象的系统，多年来一直是广受玩家欢迎的重要特性。通过个性化定制自己所控制的虚拟形象，玩家能够在游戏的沉浸感和互动感方面获得显著提升的体验。这种定制化不仅满足了玩家表达个性的需求，更重要的是增强了玩家与游戏世界的情感连接，从而提高游戏的长期留存率和商业价值。现代玩家对于角色外观的追求已经远超基础的功能需求，他们期望能够创造出独特且美观的虚拟形象，这推动了游戏角色智能创建技术的持续发展。 在这一领域，网易伏羲实验室作为业界领先的AI技术团队，在智能捏脸技术方面持续探索多年，已经发表了多篇高质量学术论文，并形成了相对成熟和完善的面部智能创建技术方案。这些研究成果不仅在学术界获得了广泛认可，更在实际的游戏产品中得到了成功应用，为玩家提供了便捷高效的面部定制体验。 然而，相比之下，游戏角色的发型和服装的参数化智能生成仍然是学术界和工业界尚未完全解决","requirements":"1. 计算机视觉或图形学相关方向，硕士或博士在读；\n2. 熟悉计算机视觉或图形学领域的主流模型和算法，有3D生成，视频生成，多模态大模型，3D重建，3D人脸/头发/人体等其中一项或多项相关算法知识优先；\n3. 计算机基础扎实，熟悉TensorFlow、Pytorch等框架，能熟练运用python、C/C++实现算法；\n4. 关注领域内的最新进展，在相关领域顶级会议（CVPR/ICCV/ECCV/NIPS/SIGGRAPH等）发表过高质量论文者优先；\n5. 专注、自驱，有强烈的探索精神及深入思考的能力。 6. 有良好的团队合作和沟通能力。","description":"","jdComplete":false,"sourceStatus":null}];
